import { AVPlaybackStatus, Audio } from "expo-av";

// Mock AppState
const mockAppStateSubscription = { remove: jest.fn() };
jest.mock("react-native", () => ({
  AppState: {
    currentState: "active",
    addEventListener: jest.fn(() => mockAppStateSubscription),
  },
}));

// Define a type for the mock sound instances with only the mocked members used by SoundManager
interface MockSoundInstance {
  loadAsync: jest.Mock;
  playAsync: jest.Mock;
  replayAsync: jest.Mock;
  stopAsync: jest.Mock;
  getStatusAsync: jest.Mock<Promise<AVPlaybackStatus>>;
  pauseAsync: jest.Mock;
  unloadAsync: jest.Mock;
  setVolumeAsync: jest.Mock; // Added for fading functionality
  // StopAsync is not used in SoundManager, removed
  // setOnPlaybackStatusUpdate is not used in SoundManager, removed
  // setIsLoopingAsync is not used in SoundManager, removed

  // Add minimal properties required to satisfy the tests or avoid type errors
  _loaded?: boolean; // Mark as optional if not always used
  _loading?: boolean; // Mark as optional
  _key?: number | string; // Mark as optional
  _lastStatusUpdate?: AVPlaybackStatus | null; // Mark as optional
  _lastStatusUpdateTime?: number | null; // Mark as optional
  _subscriptions?: unknown[]; // Use unknown[] instead of any[]
  _eventEmitter?: { addListener: jest.Mock; removeListener: jest.Mock }; // More specific type
  _coalesceStatusUpdatesInMillis?: number; // Mark as optional
  _onPlaybackStatusUpdate?: ((status: AVPlaybackStatus) => void) | null; // Mark as optional
}

// File-level mock for expo-av
const mockSoundInstances: MockSoundInstance[] = [];

jest.mock("expo-av", () => ({
  Audio: {
    Sound: {
      createAsync: jest.fn().mockImplementation(() => {
        const instance: MockSoundInstance = {
          loadAsync: jest.fn().mockResolvedValue(undefined),
          playAsync: jest.fn().mockResolvedValue(undefined),
          replayAsync: jest.fn().mockResolvedValue(undefined),
          stopAsync: jest.fn().mockResolvedValue(undefined),
          getStatusAsync: jest.fn().mockResolvedValue({
            isLoaded: true,
            isPlaying: false,
            durationMillis: 1000,
            positionMillis: 0,
            didJustFinish: false,
            isLooping: false,
            shouldPlay: false,
            progressUpdateIntervalMillis: 500,
            uri: "test-uri",
          } as AVPlaybackStatus),
          pauseAsync: jest.fn().mockResolvedValue(undefined),
          unloadAsync: jest.fn().mockResolvedValue(undefined),
          setVolumeAsync: jest.fn().mockResolvedValue(undefined),
          _loaded: false,
          _loading: false,
          _key: Math.random(),
          _lastStatusUpdate: null,
          _lastStatusUpdateTime: null,
          _subscriptions: [],
          _eventEmitter: { addListener: jest.fn(), removeListener: jest.fn() },
          _coalesceStatusUpdatesInMillis: 0,
          _onPlaybackStatusUpdate: null,
        };
        mockSoundInstances.push(instance);
        return Promise.resolve({ sound: instance });
      }),
    },
    setAudioModeAsync: jest.fn().mockResolvedValue(undefined),
    InterruptionModeIOS: {},
    InterruptionModeAndroid: {},
    PitchCorrectionQuality: {},
  },
}));

// Mock the audio files
jest.mock("../../../assets/audio/Neutral.wav", () => "test-file-stub");
jest.mock("../../../assets/audio/Success.wav", () => "test-file-stub");
jest.mock("../../../assets/audio/Negative.wav", () => "test-file-stub");

import { SoundManager as ActualSoundManager } from "../SoundManager";

interface SoundManagerType {
  init: () => Promise<void>;
  playSuccess: () => Promise<void>;
  playNegative: () => Promise<void>;
  playBackgroundMusic: () => Promise<void>;
  pauseBackgroundMusic: () => Promise<void>;
  unload: () => Promise<void>;
  fadeIn: (sound: any, options?: any) => Promise<void>;
  fadeOut: (sound: any, options?: any) => Promise<void>;
  crossfade: (fromSound: any, toSound: any, options?: any) => Promise<void>;
  cancelFade: (sound: any) => void;
  fadeInBackgroundMusic: (options?: any) => Promise<void>;
  fadeOutBackgroundMusic: (options?: any) => Promise<void>;
  playNegativeWithFadeIn: (options?: any) => Promise<void>;
}

describe("SoundManager", () => {
  let SoundManager: SoundManagerType;

  beforeEach(() => {
    // Clear mock calls and instances before each test
    jest.clearAllMocks();
    mockSoundInstances.length = 0; // Clear the instances array
    console.error = jest.fn(); // Mock console.error to avoid noise in tests
    console.warn = jest.fn(); // Mock console.warn to avoid noise in tests

    // Assign SoundManager for each test
    SoundManager = ActualSoundManager;
  });

  describe("init", () => {
    it("should set audio mode, create 3 sound instances, and play neutral sound", async () => {
      await SoundManager.init();

      // Verify audio mode was set
      expect(Audio.setAudioModeAsync).toHaveBeenCalledWith({
        allowsRecordingIOS: false,
        staysActiveInBackground: false,
        playsInSilentModeIOS: true,
        shouldDuckAndroid: false,
      });

      // Audio.Sound.createAsync should be called 3 times during init
      expect(Audio.Sound.createAsync).toHaveBeenCalledTimes(3);
      expect(mockSoundInstances.length).toBe(3);

      // Check the createAsync calls were made with correct parameters
      expect(Audio.Sound.createAsync).toHaveBeenNthCalledWith(
        1,
        "test-file-stub",
        {
          isLooping: true,
          shouldPlay: false,
          // High-quality playback settings
          volume: 1.0,
          rate: 1.0,
          shouldCorrectPitch: false, // Disable pitch correction for better quality
        },
        // Audio session status callback for quality monitoring
        expect.any(Function)
      );
      expect(Audio.Sound.createAsync).toHaveBeenNthCalledWith(
        2,
        "test-file-stub",
        {
          shouldPlay: false,
          volume: 1.0,
          rate: 1.0,
          shouldCorrectPitch: false, // Disable pitch correction for better quality
        }
      );
      expect(Audio.Sound.createAsync).toHaveBeenNthCalledWith(
        3,
        "test-file-stub",
        {
          shouldPlay: false,
          volume: 1.0,
          rate: 1.0,
          shouldCorrectPitch: false, // Disable pitch correction for better quality
        }
      );

      // Verify neutral sound starts playing
      expect(mockSoundInstances[0].replayAsync).toHaveBeenCalledTimes(1);
    });

    it("should log error if setting audio mode fails", async () => {
      // Setup specific mock behavior for setAudioModeAsync to fail
      (Audio.setAudioModeAsync as jest.Mock).mockRejectedValueOnce(
        new Error("Audio mode failed")
      );

      await SoundManager.init();
      expect(console.error).toHaveBeenCalledWith(
        "Error loading sounds:",
        expect.any(Error)
      );
    });

    it("should log error if creating sounds fails", async () => {
      // Setup specific mock behavior for createAsync to fail
      (Audio.Sound.createAsync as jest.Mock).mockRejectedValueOnce(
        new Error("Create sound failed")
      );

      await SoundManager.init();
      expect(console.error).toHaveBeenCalledWith(
        "Error loading sounds:",
        expect.any(Error)
      );
    });
  });

  describe("playSuccess", () => {
    beforeEach(async () => {
      // Ensure a fresh SoundManager with sounds loaded for these tests
      await SoundManager.init();
      // Clear calls from init itself
      if (mockSoundInstances[1]) {
        mockSoundInstances[1].replayAsync.mockClear();
        mockSoundInstances[1].stopAsync.mockClear();
        mockSoundInstances[1].getStatusAsync.mockClear();
      }
    });

    it("should replay success sound when not playing", async () => {
      mockSoundInstances[1].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: false,
      } as AVPlaybackStatus);

      await SoundManager.playSuccess();

      expect(mockSoundInstances[1].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[1].stopAsync).not.toHaveBeenCalled();
      expect(mockSoundInstances[1].replayAsync).toHaveBeenCalledTimes(1);
    });

    it("should stop and replay success sound when already playing", async () => {
      mockSoundInstances[1].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: true,
      } as AVPlaybackStatus);

      await SoundManager.playSuccess();

      expect(mockSoundInstances[1].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[1].stopAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[1].replayAsync).toHaveBeenCalledTimes(1);
    });

    it("should warn if success sound not initialized", async () => {
      // Don't call init, so sounds are not initialized
      // SoundManager is already assigned in main beforeEach
      await SoundManager.playSuccess();
      expect(console.warn).toHaveBeenCalledWith(
        "Success sound not initialized"
      );
    });

    it("should log error if playing success sound fails", async () => {
      mockSoundInstances[1].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: false,
      } as AVPlaybackStatus);
      mockSoundInstances[1].replayAsync.mockRejectedValueOnce(
        new Error("Play success failed")
      );
      await SoundManager.playSuccess();
      expect(console.error).toHaveBeenCalledWith(
        "Error playing success sound:",
        expect.any(Error)
      );
    });
  });

  describe("playNegative", () => {
    beforeEach(async () => {
      await SoundManager.init();
      if (mockSoundInstances[2]) {
        mockSoundInstances[2].replayAsync.mockClear();
        mockSoundInstances[2].stopAsync.mockClear();
        mockSoundInstances[2].getStatusAsync.mockClear();
      }
    });

    it("should replay negative sound when not playing", async () => {
      mockSoundInstances[2].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: false,
      } as AVPlaybackStatus);

      await SoundManager.playNegative();

      expect(mockSoundInstances[2].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[2].stopAsync).not.toHaveBeenCalled();
      expect(mockSoundInstances[2].replayAsync).toHaveBeenCalledTimes(1);
    });

    it("should stop and replay negative sound when already playing", async () => {
      mockSoundInstances[2].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: true,
      } as AVPlaybackStatus);

      await SoundManager.playNegative();

      expect(mockSoundInstances[2].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[2].stopAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[2].replayAsync).toHaveBeenCalledTimes(1);
    });

    it("should warn if negative sound not initialized", async () => {
      // Don't call init, so sounds are not initialized
      // SoundManager is already assigned in main beforeEach
      await SoundManager.playNegative();
      expect(console.warn).toHaveBeenCalledWith(
        "Negative sound not initialized"
      );
    });

    it("should log error if playing negative sound fails", async () => {
      mockSoundInstances[2].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: false,
      } as AVPlaybackStatus);
      mockSoundInstances[2].replayAsync.mockRejectedValueOnce(
        new Error("Play negative failed")
      );
      await SoundManager.playNegative();
      expect(console.error).toHaveBeenCalledWith(
        "Error playing negative sound:",
        expect.any(Error)
      );
    });
  });

  describe("playBackgroundMusic", () => {
    beforeEach(async () => {
      await SoundManager.init();
      // Clear specific mocks if init calls them
      if (mockSoundInstances[0]) {
        mockSoundInstances[0].getStatusAsync.mockClear();
        mockSoundInstances[0].playAsync.mockClear();
      }
    });

    it("should play background music if loaded and not playing", async () => {
      mockSoundInstances[0].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: false,
      } as AVPlaybackStatus); // Use AVPlaybackStatus
      await SoundManager.playBackgroundMusic();
      expect(mockSoundInstances[0].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[0].playAsync).toHaveBeenCalledTimes(1);
    });

    it("should not play background music if already playing", async () => {
      mockSoundInstances[0].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: true,
      } as AVPlaybackStatus); // Use AVPlaybackStatus
      await SoundManager.playBackgroundMusic();
      expect(mockSoundInstances[0].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[0].playAsync).not.toHaveBeenCalled();
    });

    it("should warn if neutral sound not initialized", async () => {
      // Don't call init, so sounds are not initialized
      // SoundManager is already assigned in main beforeEach
      await SoundManager.playBackgroundMusic();
      expect(console.warn).toHaveBeenCalledWith(
        "Neutral sound not initialized"
      );
    });

    it("should log error if getStatusAsync fails", async () => {
      mockSoundInstances[0].getStatusAsync.mockRejectedValueOnce(
        new Error("Get status failed")
      );
      await SoundManager.playBackgroundMusic();
      expect(console.error).toHaveBeenCalledWith(
        "Error playing background music:",
        expect.any(Error)
      );
    });
  });

  describe("pauseBackgroundMusic", () => {
    beforeEach(async () => {
      await SoundManager.init();
      if (mockSoundInstances[0]) {
        mockSoundInstances[0].getStatusAsync.mockClear();
        mockSoundInstances[0].pauseAsync.mockClear();
      }
    });

    it("should pause background music if loaded and playing", async () => {
      mockSoundInstances[0].getStatusAsync.mockResolvedValueOnce({
        isLoaded: true,
        isPlaying: true,
      } as AVPlaybackStatus); // Use AVPlaybackStatus
      await SoundManager.pauseBackgroundMusic();
      expect(mockSoundInstances[0].getStatusAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[0].pauseAsync).toHaveBeenCalledTimes(1);
    });

    it("should warn if neutral sound not initialized for pause", async () => {
      // Don't call init, so sounds are not initialized
      // SoundManager is already assigned in main beforeEach
      await SoundManager.pauseBackgroundMusic();
      expect(console.warn).toHaveBeenCalledWith(
        "Neutral sound not initialized"
      );
    });

    it("should log error if getStatusAsync fails for pause", async () => {
      mockSoundInstances[0].getStatusAsync.mockRejectedValueOnce(
        new Error("Get status failed")
      );
      await SoundManager.pauseBackgroundMusic();
      expect(console.error).toHaveBeenCalledWith(
        "Error pausing background music:",
        expect.any(Error)
      );
    });
  });

  // Corrected test description and method call to match actual SoundManager.unload
  describe("unload", () => {
    beforeEach(async () => {
      await SoundManager.init();
      if (mockSoundInstances[0]) mockSoundInstances[0].unloadAsync.mockClear();
      if (mockSoundInstances[1]) mockSoundInstances[1].unloadAsync.mockClear();
      if (mockSoundInstances[2]) mockSoundInstances[2].unloadAsync.mockClear();
    });

    it("should unload all sounds", async () => {
      await SoundManager.unload(); // Corrected method call
      expect(mockSoundInstances[0].unloadAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[1].unloadAsync).toHaveBeenCalledTimes(1);
      expect(mockSoundInstances[2].unloadAsync).toHaveBeenCalledTimes(1);
    });

    it("should log error if unloading sounds fails", async () => {
      mockSoundInstances[0].unloadAsync.mockRejectedValueOnce(
        new Error("Unload failed")
      );
      await SoundManager.unload(); // Corrected method call
      expect(console.error).toHaveBeenCalledWith(
        "Error unloading sounds:",
        expect.any(Error)
      );
    });
  });

  describe("Audio Fading", () => {
    beforeEach(async () => {
      await SoundManager.init();
      jest.clearAllMocks();

      // Reset all sound instances to default state
      mockSoundInstances.forEach((instance) => {
        instance.getStatusAsync.mockResolvedValue({
          isLoaded: true,
          isPlaying: false,
          durationMillis: 1000,
          positionMillis: 0,
          didJustFinish: false,
          isLooping: false,
          shouldPlay: false,
          progressUpdateIntervalMillis: 500,
          uri: "test-uri",
        } as AVPlaybackStatus);
        instance.setVolumeAsync.mockClear();
        instance.playAsync.mockClear();
        instance.pauseAsync.mockClear();
      });
    });

    describe("fadeIn", () => {
      it("should fade in a sound from volume 0 to 1", async () => {
        const soundInstance = mockSoundInstances[0];

        await SoundManager.fadeIn(soundInstance as any, {
          duration: 100,
          steps: 5,
        });

        // Should start playing at volume 0
        expect(soundInstance.setVolumeAsync).toHaveBeenCalledWith(0);
        expect(soundInstance.playAsync).toHaveBeenCalledTimes(1);

        // Should gradually increase volume to 1
        expect(soundInstance.setVolumeAsync).toHaveBeenCalledWith(1);
        expect(soundInstance.setVolumeAsync.mock.calls.length).toBeGreaterThan(
          1
        );
      });

      it("should not start fade if sound is not loaded", async () => {
        const soundInstance = mockSoundInstances[0];
        soundInstance.getStatusAsync.mockResolvedValueOnce({
          isLoaded: false,
          isPlaying: false,
        } as AVPlaybackStatus);

        await SoundManager.fadeIn(soundInstance as any);

        expect(soundInstance.setVolumeAsync).not.toHaveBeenCalled();
        expect(console.warn).toHaveBeenCalledWith(
          "SoundManager: Sound not loaded for fade in"
        );
      });

      it("should not start fade when app is in background", async () => {
        // Simulate app going to background
        const mockHandleAppStateChange = jest.fn();
        (
          require("react-native").AppState.addEventListener as jest.Mock
        ).mockImplementation(
          (event: string, callback: (state: string) => void) => {
            if (event === "change") {
              callback("background");
            }
            return mockAppStateSubscription;
          }
        );

        // Reinitialize to apply background state
        await SoundManager.unload();
        await SoundManager.init();

        const soundInstance = mockSoundInstances[0];
        await SoundManager.fadeIn(soundInstance as any);

        expect(soundInstance.setVolumeAsync).not.toHaveBeenCalled();
      });
    });

    describe("fadeOut", () => {
      it("should fade out a sound from volume 1 to 0", async () => {
        const soundInstance = mockSoundInstances[0];
        soundInstance.getStatusAsync.mockResolvedValue({
          isLoaded: true,
          isPlaying: true,
        } as AVPlaybackStatus);

        await SoundManager.fadeOut(soundInstance as any, {
          duration: 100,
          steps: 5,
        });

        // Should gradually decrease volume to 0
        expect(soundInstance.setVolumeAsync).toHaveBeenCalledWith(0);
        expect(soundInstance.setVolumeAsync.mock.calls.length).toBeGreaterThan(
          1
        );

        // Should pause after fade completes
        expect(soundInstance.pauseAsync).toHaveBeenCalledTimes(1);
      });

      it("should not fade if sound is not playing", async () => {
        const soundInstance = mockSoundInstances[0];
        soundInstance.getStatusAsync.mockResolvedValueOnce({
          isLoaded: true,
          isPlaying: false,
        } as AVPlaybackStatus);

        await SoundManager.fadeOut(soundInstance as any);

        expect(soundInstance.setVolumeAsync).not.toHaveBeenCalled();
        expect(console.warn).toHaveBeenCalledWith(
          "SoundManager: Sound not playing for fade out"
        );
      });
    });

    describe("crossfade", () => {
      it("should crossfade between two sounds", async () => {
        const fromSound = mockSoundInstances[0];
        const toSound = mockSoundInstances[1];

        fromSound.getStatusAsync.mockResolvedValue({
          isLoaded: true,
          isPlaying: true,
        } as AVPlaybackStatus);

        toSound.getStatusAsync.mockResolvedValue({
          isLoaded: true,
          isPlaying: false,
        } as AVPlaybackStatus);

        await SoundManager.crossfade(fromSound as any, toSound as any, {
          duration: 100,
          steps: 5,
        });

        // Should start the new sound at volume 0
        expect(toSound.setVolumeAsync).toHaveBeenCalledWith(0);
        expect(toSound.playAsync).toHaveBeenCalledTimes(1);

        // Should pause the old sound after crossfade
        expect(fromSound.pauseAsync).toHaveBeenCalledTimes(1);

        // Both sounds should have volume adjustments
        expect(fromSound.setVolumeAsync.mock.calls.length).toBeGreaterThan(1);
        expect(toSound.setVolumeAsync.mock.calls.length).toBeGreaterThan(1);
      });
    });

    describe("fadeInBackgroundMusic", () => {
      it("should fade in the background music", async () => {
        const neutralSound = mockSoundInstances[0]; // First instance is neutral sound

        await SoundManager.fadeInBackgroundMusic({ duration: 100, steps: 5 });

        expect(neutralSound.setVolumeAsync).toHaveBeenCalledWith(0);
        expect(neutralSound.playAsync).toHaveBeenCalledTimes(1);
        expect(neutralSound.setVolumeAsync).toHaveBeenCalledWith(1);
      });

      it("should warn if neutral sound is not initialized", async () => {
        await SoundManager.unload();

        await SoundManager.fadeInBackgroundMusic();

        expect(console.warn).toHaveBeenCalledWith(
          "SoundManager: Neutral sound not initialized for fade in"
        );
      });
    });

    describe("fadeOutBackgroundMusic", () => {
      it("should fade out the background music", async () => {
        const neutralSound = mockSoundInstances[0]; // First instance is neutral sound
        neutralSound.getStatusAsync.mockResolvedValue({
          isLoaded: true,
          isPlaying: true,
        } as AVPlaybackStatus);

        await SoundManager.fadeOutBackgroundMusic({ duration: 100, steps: 5 });

        expect(neutralSound.setVolumeAsync).toHaveBeenCalledWith(0);
        expect(neutralSound.pauseAsync).toHaveBeenCalledTimes(1);
      });

      it("should warn if neutral sound is not initialized", async () => {
        await SoundManager.unload();

        await SoundManager.fadeOutBackgroundMusic();

        expect(console.warn).toHaveBeenCalledWith(
          "SoundManager: Neutral sound not initialized for fade out"
        );
      });
    });

    describe("cancelFade", () => {
      it("should cancel an active fade operation", () => {
        const soundInstance = mockSoundInstances[0];

        SoundManager.cancelFade(soundInstance as any);

        expect(console.log).toHaveBeenCalledWith(
          "SoundManager: Fade operation cancelled"
        );
      });
    });

    describe("fade curve calculations", () => {
      it("should handle linear fade curves", async () => {
        const soundInstance = mockSoundInstances[0];

        await SoundManager.fadeIn(soundInstance as any, {
          duration: 100,
          steps: 4,
          curve: "linear",
        });

        // Verify linear progression: 0, 0.25, 0.5, 0.75, 1
        const volumeCalls = soundInstance.setVolumeAsync.mock.calls;
        expect(volumeCalls).toContainEqual([0]);
        expect(volumeCalls).toContainEqual([0.25]);
        expect(volumeCalls).toContainEqual([0.5]);
        expect(volumeCalls).toContainEqual([0.75]);
        expect(volumeCalls).toContainEqual([1]);
      });

      it("should handle exponential fade curves", async () => {
        const soundInstance = mockSoundInstances[0];

        await SoundManager.fadeIn(soundInstance as any, {
          duration: 100,
          steps: 4,
          curve: "exponential",
        });

        // Verify exponential progression (squared values)
        const volumeCalls = soundInstance.setVolumeAsync.mock.calls;
        expect(volumeCalls).toContainEqual([0]); // 0^2
        expect(volumeCalls).toContainEqual([0.0625]); // 0.25^2
        expect(volumeCalls).toContainEqual([0.25]); // 0.5^2
        expect(volumeCalls).toContainEqual([0.5625]); // 0.75^2
        expect(volumeCalls).toContainEqual([1]); // 1^2
      });
    });
  });

  describe("playNegativeWithFadeIn", () => {
    beforeEach(async () => {
      await SoundManager.init();
      if (mockSoundInstances[2]) {
        mockSoundInstances[2].setVolumeAsync.mockClear();
        mockSoundInstances[2].replayAsync.mockClear();
        mockSoundInstances[2].getStatusAsync.mockResolvedValue({
          isLoaded: true,
          isPlaying: false,
        } as any);
      }
    });

    it("should set volume to 0, start playback, and fade in", async () => {
      await SoundManager.playNegativeWithFadeIn({ duration: 100, steps: 2 });

      // Should set volume to 0 first
      expect(mockSoundInstances[2].setVolumeAsync).toHaveBeenCalledWith(0);

      // Should start playback
      expect(mockSoundInstances[2].replayAsync).toHaveBeenCalledTimes(1);

      // Should call setVolumeAsync multiple times for fade-in (0, 0.5, 1.0)
      expect(mockSoundInstances[2].setVolumeAsync).toHaveBeenCalledTimes(4); // Initial 0 + 3 fade steps
    });

    it("should use default fade options when none provided", async () => {
      await SoundManager.playNegativeWithFadeIn();

      // Should still set volume to 0 and start playback
      expect(mockSoundInstances[2].setVolumeAsync).toHaveBeenCalledWith(0);
      expect(mockSoundInstances[2].replayAsync).toHaveBeenCalledTimes(1);
    });

    it("should not play when app is not active", async () => {
      // Mock app state as background
      jest.doMock("react-native", () => ({
        AppState: {
          currentState: "background",
          addEventListener: jest.fn(),
        },
      }));

      await SoundManager.playNegativeWithFadeIn();

      // Should not call any sound methods
      expect(mockSoundInstances[2].setVolumeAsync).not.toHaveBeenCalled();
      expect(mockSoundInstances[2].replayAsync).not.toHaveBeenCalled();
    });
  });
});
